1→import { createHash } from 'node:crypto';
2→import { execFile } from 'node:child_process';
3→import { existsSync, mkdirSync, mkdtempSync, readFileSync, realpathSync, rmSync, statSync, writeFileSync } from 'node:fs';
4→import { tmpdir } from 'node:os';
5→import { basename, dirname, extname, isAbsolute, join, relative, resolve } from 'node:path';
6→import { pathToFileURL } from 'node:url';
7→import { promisify } from 'node:util';
8→import { deserialize } from 'node:v8';
9→
10→const runFile = promisify(execFile);
11→const sha = (value) => createHash('sha256').update(value).digest('hex');
12→const typed = (message, code, fields = {}) => Object.assign(new Error(message), { code, ...fields });
13→const abort = (ctx) => { if (ctx?.signal?.aborted) throw typed('behavior observation cancelled', 'cancelled'); };
14→const stable = (value) => {
15→  if (Array.isArray(value)) return `[${value.map(stable).join(',')}]`;
16→  if (value && typeof value === 'object') return `{${Object.keys(value).sort().map((key) => `${JSON.stringify(key)}:${stable(value[key])}`).join(',')}}`;
17→  return JSON.stringify(value);
18→};
19→const RUNNER = String.raw`
20→const [targetUrl, exportName, encoded] = process.argv.slice(1);
21→const emit = process.stdout.write.bind(process.stdout);
22→const hardExit = process.exit.bind(process);
23→const removeAllListeners = process.removeAllListeners.bind(process);
24→const parse = JSON.parse.bind(JSON);
25→const arrayIsArray = Array.isArray.bind(Array);
26→const arrayPush = Function.call.bind(Array.prototype.push);
27→const objectCreate = Object.create.bind(Object);
28→const objectIs = Object.is.bind(Object);
29→const numberIsNaN = Number.isNaN.bind(Number);
30→const stringValue = String;
31→const bufferToString = Function.call.bind(Buffer.prototype.toString);
32→const { serialize } = await import('node:v8');
33→const corpus = parse(Buffer.from(encoded, 'base64').toString('utf8'));
34→const module = await import(targetUrl);
35→const fn = module[exportName];
36→if (typeof fn !== 'function') throw Object.assign(new Error('named export is not a function'), { code: 'EXPORT_NOT_FUNCTION' });
37→const observations = [];
38→for (let caseIndex = 0; caseIndex < corpus.length; caseIndex += 1) {
39→  try {
40→    const value = await fn(corpus[caseIndex]);
41→    const item = objectCreate(null); item.caseIndex = caseIndex; item.kind = 'return'; item.valueBytes = bufferToString(serialize(value), 'base64');
42→    if (value === undefined) item.valueType = 'undefined';
43→    else if (typeof value === 'number' && numberIsNaN(value)) { item.valueType = 'number'; item.numberClass = 'NaN'; }
44→    else if (typeof value === 'number' && objectIs(value, -0)) { item.valueType = 'number'; item.numberClass = '-0'; }
45→    else if (value === Infinity || value === -Infinity) { item.valueType = 'number'; item.numberClass = stringValue(value); }
46→    else if (value === null || typeof value === 'string' || typeof value === 'boolean' || typeof value === 'number') item.value = value;
47→    else if (typeof value === 'bigint') { item.valueType = 'bigint'; item.value = stringValue(value); }
48→    else item.valueType = arrayIsArray(value) ? 'array' : typeof value;
49→    arrayPush(observations, item);
50→  } catch (error) {
51→    const item = objectCreate(null); item.caseIndex = caseIndex; item.kind = 'throw'; item.name = stringValue(error?.name ?? 'Error'); item.message = stringValue(error?.message ?? error); item.code = error?.code ?? error?.cause?.code ?? null;
52→    arrayPush(observations, item);
53→  }
54→}
55→const frame = bufferToString(serialize({ nodeVersion: process.version, observations }), 'base64');
56→removeAllListeners('beforeExit'); removeAllListeners('exit');
57→emit('\nBATON_BEHAVIOR_RESULT:' + frame + '\n');
58→hardExit(0);
59→`;
60→
61→function bounded(items, tokens) {
62→  const out = [];
63→  for (const item of items) {
64→    if (Buffer.byteLength(JSON.stringify([...out, item])) > tokens * 4) break;
65→    out.push(item);
66→  }
67→  return out;
68→}
