70→function validatePath(path) {
71→  if (typeof path !== 'string' || path.length === 0 || isAbsolute(path) || path.split(/[\\/]+/).includes('..')) throw typed('behavior target path escapes root', 'path_escape');
72→  if (!['.js', '.mjs'].includes(extname(path).toLowerCase())) throw typed('behavior fingerprint supports dependency-free JavaScript ESM only', 'unsupported_language');
73→  return path;
74→}
75→
76→function target(root, path, maxSourceBytes) {
77→  if (typeof root !== 'string' || root.length === 0) throw new TypeError('behavior root required');
78→  const realRoot = realpathSync(root); let realTarget;
79→  try { realTarget = realpathSync(resolve(realRoot, validatePath(path))); }
80→  catch (error) { if (error?.code === 'path_escape' || error?.code === 'unsupported_language') throw error; throw typed('behavior target unavailable', 'target_unavailable'); }
81→  const rel = relative(realRoot, realTarget);
82→  if (rel === '' || rel === '..' || rel.startsWith(`..${process.platform === 'win32' ? '\\' : '/'}`) || isAbsolute(rel)) throw typed('behavior target escapes root', 'path_escape');
83→  if (!statSync(realTarget).isFile()) throw typed('behavior target must be a file', 'target_unavailable');
84→  const source = readFileSync(realTarget); if (source.byteLength > maxSourceBytes) throw typed('behavior source exceeds deployment budget', 'source_too_large');
85→  return { realTarget, source, sourceDigest: sha(source) };
86→}
87→
88→function corpusBytes(corpus, maxCorpusCases, maxInputBytes) {
89→  if (!Array.isArray(corpus)) throw new TypeError('behavior corpus must be an array');
90→  if (corpus.length === 0 || corpus.length > maxCorpusCases) throw typed('behavior corpus exceeds deployment case budget', 'corpus_too_large');
91→  const json = (value, seen = new Set()) => {
92→    if (value === null || typeof value === 'string' || typeof value === 'boolean') return;
93→    if (typeof value === 'number') { if (!Number.isFinite(value)) throw typed('behavior corpus must contain finite JSON numbers', 'invalid_corpus'); return; }
94→    if (typeof value !== 'object' || seen.has(value)) throw typed('behavior corpus must contain only acyclic JSON values', 'invalid_corpus');
95→    seen.add(value);
96→    if (Array.isArray(value)) for (const item of value) json(item, seen);
97→    else {
98→      const proto = Object.getPrototypeOf(value); if (proto !== Object.prototype && proto !== null) throw typed('behavior corpus objects must be plain JSON objects', 'invalid_corpus');
99→      for (const item of Object.values(value)) json(item, seen);
100→    }
101→    seen.delete(value);
102→  };
103→  json(corpus);
104→  let serialized;
105→  try { serialized = JSON.stringify(corpus); } catch { throw typed('behavior corpus must be JSON serializable', 'invalid_corpus'); }
106→  if (serialized === undefined || Buffer.byteLength(serialized) > maxInputBytes) throw typed('behavior corpus exceeds deployment byte budget', 'corpus_too_large');
107→  return { serialized, digest: sha(serialized) };
108→}
109→
110→export class AtlasBehaviorFingerprint {
111→  constructor(opts = {}) {
112→    if (!opts.artifactRoot) throw new TypeError('behavior artifactRoot required');
113→    for (const key of ['maxSourceBytes', 'maxCorpusCases', 'maxInputBytes', 'maxOutputBytes', 'maxArtifactBytes', 'timeoutMs']) {
114→      if (!Number.isSafeInteger(opts[key]) || opts[key] <= 0) throw new TypeError(`${key} must be deployment-derived`);
115→    }
116→    this.artifactRoot = opts.artifactRoot;
117→    this.maxSourceBytes = opts.maxSourceBytes;
118→    this.maxCorpusCases = opts.maxCorpusCases;
119→    this.maxInputBytes = opts.maxInputBytes;
120→    this.maxOutputBytes = opts.maxOutputBytes;
121→    this.maxArtifactBytes = opts.maxArtifactBytes;
122→    this.timeoutMs = opts.timeoutMs;
123→    this.nodePath = opts.nodePath ?? process.execPath;
124→    this.now = opts.now ?? Date.now;
125→    this.record = opts.record ?? null;
126→    mkdirSync(this.artifactRoot, { recursive: true, mode: 0o700 });
127→  }
128→
129→  card() {
130→    return Object.freeze({
131→      name: 'atlas-behavior-fingerprint', version: '0.1.0', underlying: [`node-permission-model@${process.version}`],
132→      ops: {
133→        'behavior.fingerprint': { deterministic: true, latency_class: 'bounded_batch', side_effects: 'executes_target_in_throwaway_permission_sandbox', reverifiable: true },
134→        'behavior.compare': { deterministic: true, latency_class: 'bounded_batch', side_effects: 'executes_targets_in_throwaway_permission_sandboxes', reverifiable: true },
135→      },
136→      limitations: ['dependency-free JavaScript ESM named exports only', 'pinned-corpus observation is not semantic equivalence', 'no input generation or coverage claim', 'filesystem writes, network, child processes, and workers denied'],
137→    });
138→  }
139→
140→  async _once(source, exportName, corpus, ctx) {
141→    abort(ctx);
142→    // macOS exposes its temp root through /var -> /private/var. Node's permission resolver uses
143→    // canonical paths, so grant the canonical sandbox rather than the lexical symlink path.
144→    const sandbox = realpathSync(mkdtempSync(join(tmpdir(), 'baton-behavior-sandbox-')));
145→    const targetPath = join(sandbox, 'target.mjs'); writeFileSync(targetPath, source, { mode: 0o400 });
146→    try {
147→      const encoded = Buffer.from(corpus).toString('base64');
148→      const { stdout } = await runFile(this.nodePath, [
149→        '--permission', `--allow-fs-read=${sandbox}`, '--input-type=module', '-e', RUNNER,
150→        pathToFileURL(targetPath).href, exportName, encoded,
151→      ], {
152→        encoding: 'utf8', timeout: this.timeoutMs, maxBuffer: this.maxOutputBytes, signal: ctx?.signal,
153→        env: { LANG: 'C', LC_ALL: 'C', TZ: 'UTC', NODE_NO_WARNINGS: '1' },
154→      });
155→      const frames = stdout.split('\n').filter((line) => line.startsWith('BATON_BEHAVIOR_RESULT:'));
156→      if (frames.length !== 1) throw typed('behavior child produced an ambiguous result channel', 'observation_protocol');
157→      let envelope;
158→      try { envelope = deserialize(Buffer.from(frames[0].slice('BATON_BEHAVIOR_RESULT:'.length), 'base64')); }
159→      catch { throw typed('behavior child result frame is invalid', 'observation_protocol'); }
160→      if (!envelope || typeof envelope.nodeVersion !== 'string' || !Array.isArray(envelope.observations)) throw typed('behavior child result frame has invalid schema', 'observation_protocol');
161→      const observations = envelope.observations;
162→      if (Buffer.byteLength(JSON.stringify(observations)) > this.maxOutputBytes) throw typed('behavior observations exceed deployment budget', 'output_too_large');
163→      if (observations.some((item) => item.kind === 'throw' && item.code === 'ERR_ACCESS_DENIED')) throw typed('target attempted an operation denied by the permission sandbox', 'sandbox_violation');
164→      return { observations, nodeVersion: envelope.nodeVersion };
165→    } catch (error) {
166→      if (['sandbox_violation', 'output_too_large', 'execution_failed', 'observation_protocol'].includes(error?.code)) throw error;
167→      if (error?.name === 'AbortError' || error?.code === 'ABORT_ERR') throw typed('behavior observation cancelled', 'cancelled');
168→      if (error?.killed || error?.signal || error?.code === 'ETIMEDOUT') throw typed('behavior observation exceeded execution deadline', 'execution_timeout');
169→      throw typed(`behavior child failed: ${error?.message ?? error}`, error?.message?.includes('EXPORT_NOT_FUNCTION') ? 'invalid_export' : 'execution_failed');
170→    } finally {
171→      rmSync(sandbox, { recursive: true, force: true });
172→    }
173→  }
174→
175→  async _observe(root, path, exportName, corpus, ctx) {
176→    if (typeof exportName !== 'string' || !/^[A-Za-z_$][\w$]*$/.test(exportName)) throw typed('valid named export required', 'invalid_export');
177→    const resolved = target(root, path, this.maxSourceBytes); const input = corpusBytes(corpus, this.maxCorpusCases, this.maxInputBytes);
178→    const first = await this._once(resolved.source, exportName, input.serialized, ctx); abort(ctx);
179→    const second = await this._once(resolved.source, exportName, input.serialized, ctx);
180→    if (first.nodeVersion !== second.nodeVersion || stable(first.observations) !== stable(second.observations)) throw typed('target observations differ across isolated repetitions', 'nondeterministic');
181→    return {
182→      path, exportName, sourceDigest: resolved.sourceDigest, corpusDigest: input.digest, observations: first.observations,
183→      nodeVersion: first.nodeVersion,
184→      sandbox: { permissionModel: true, fsRead: 'isolated_target_only', fsWrite: 'denied', network: 'denied', childProcess: 'denied', workers: 'denied' },
185→    };
186→  }
187→
188→  _writeResult(op, artifact, items, ctx, started) {
189→    const serialized = `${JSON.stringify(artifact)}\n`; const digest = sha(serialized);
190→    if (Buffer.byteLength(serialized) > this.maxArtifactBytes) throw typed('behavior artifact exceeds deployment budget', 'artifact_too_large');
191→    const path = join(this.artifactRoot, `${digest}.json`);
192→    if (existsSync(path) && sha(readFileSync(path)) !== digest) throw typed('behavior artifact integrity failure', 'artifact_integrity');
193→    if (!existsSync(path)) writeFileSync(path, serialized, { mode: 0o600, flag: 'wx' });
194→    const payload = bounded(items, ctx.budgetTokens); const truncated = payload.length < items.length;
195→    const kind = op === 'behavior.fingerprint' ? 'behavior_fingerprint' : 'behavior_comparison';
196→    const meaning = op === 'behavior.fingerprint' ? 'observed_pinned_corpus_not_semantic_equivalence' : 'observed_corpus_agreement_not_semantic_equivalence';
197→    const result = Object.freeze({
198→      op, status: truncated ? 'needs_resume' : 'ok', summary: op === 'behavior.fingerprint' ? `observed ${artifact.observations.length} pinned cases` : `${artifact.divergences.length} observed divergences`, payload,
199→      refs: [{ handle: `art:sha256:${digest}`, kind, digest, bytes: Buffer.byteLength(serialized), mediaType: `application/vnd.baton.atlas-${kind.replaceAll('_', '-')}+json`, path }],
200→      ...(truncated ? { cursor: `atlas-behavior:${digest}:${payload.length}` } : {}),
201→      cost: { tokens_out: Math.ceil(Buffer.byteLength(JSON.stringify(payload)) / 4), wall_ms: Math.max(0, this.now() - started), usd: 0, underlying: `node-permission-model@${artifact.nodeVersion}` },
202→      provenance: { artifactDigest: digest, sourceDigests: artifact.sourceDigests ?? [artifact.sourceDigest], corpusDigest: artifact.corpusDigest, exportName: artifact.exportName, nodeVersion: artifact.nodeVersion, sandbox: artifact.sandbox, deterministic: true, meaning },
203→    });
204→    this.record?.({ kind: 'capability.op.completed', actor: ctx.actor ?? 'orchestrator', op, digest, status: result.status });
205→    return result;
206→  }
207→
208→  async invoke(op, args, ctx) {
209→    if (!ctx || !Number.isSafeInteger(ctx.budgetTokens) || ctx.budgetTokens <= 0) throw new TypeError('positive budgetTokens required');
210→    if (!['behavior.fingerprint', 'behavior.compare'].includes(op)) throw typed(`unsupported behavior operation: ${op}`, 'unsupported_op');
211→    abort(ctx); const started = this.now(); this.record?.({ kind: 'capability.op.started', actor: ctx.actor ?? 'orchestrator', op });
212→    if (op === 'behavior.fingerprint') {
213→      const observed = await this._observe(ctx.root, validatePath(args?.path), args?.exportName, args?.corpus, ctx);
214→      const artifact = { schemaVersion: 1, op, ...observed };
215→      return this._writeResult(op, artifact, observed.observations, ctx, started);
216→    }
217→    const before = await this._observe(ctx.beforeRoot, validatePath(args?.beforePath), args?.exportName, args?.corpus, ctx); abort(ctx);
218→    const after = await this._observe(ctx.afterRoot, validatePath(args?.afterPath), args?.exportName, args?.corpus, ctx);
219→    const divergences = [];
220→    for (let caseIndex = 0; caseIndex < before.observations.length; caseIndex += 1) {
221→      if (stable(before.observations[caseIndex]) !== stable(after.observations[caseIndex])) divergences.push({ caseIndex, before: before.observations[caseIndex], after: after.observations[caseIndex] });
222→    }
223→    const comparison = { recordType: 'behavior_comparison', agree: divergences.length === 0, cases: before.observations.length, divergences };
224→    const artifact = {
225→      schemaVersion: 1, op, exportName: args.exportName, corpusDigest: before.corpusDigest,
226→      sourceDigests: [before.sourceDigest, after.sourceDigest], before: { path: before.path, observations: before.observations }, after: { path: after.path, observations: after.observations },
227→      nodeVersion: before.nodeVersion, sandbox: before.sandbox, divergences,
228→    };
229→    return this._writeResult(op, artifact, [comparison], ctx, started);
230→  }
231→
232→  async resume(ref, cursor, ctx) {
233→    if (!ctx || !Number.isSafeInteger(ctx.budgetTokens) || ctx.budgetTokens <= 0) throw new TypeError('positive budgetTokens required'); abort(ctx);
234→    const match = /^atlas-behavior:([a-f0-9]{64}):(\d+)$/.exec(cursor ?? ''); if (!match || match[1] !== ref?.digest) throw typed('invalid behavior cursor', 'invalid_cursor');
235→    let path; try { path = realpathSync(ref.path); } catch { throw typed('behavior artifact unavailable', 'artifact_integrity'); }
236→    const root = realpathSync(this.artifactRoot); if (path !== join(root, `${ref.digest}.json`)) throw typed('behavior artifact path escape', 'artifact_integrity');
237→    const bytes = readFileSync(path); if (sha(bytes) !== ref.digest) throw typed('behavior artifact digest mismatch', 'artifact_integrity');
238→    let artifact; try { artifact = JSON.parse(bytes); } catch { throw typed('behavior artifact JSON invalid', 'artifact_integrity'); }
239→    if (artifact.schemaVersion !== 1 || !['behavior.fingerprint', 'behavior.compare'].includes(artifact.op)) throw typed('behavior artifact schema mismatch', 'artifact_integrity');
240→    const items = artifact.op === 'behavior.fingerprint' ? artifact.observations : [{ recordType: 'behavior_comparison', agree: artifact.divergences.length === 0, cases: artifact.before.observations.length, divergences: artifact.divergences }];
241→    const offset = Number(match[2]); if (!Number.isSafeInteger(offset) || offset < 0 || offset > items.length) throw typed('invalid behavior cursor offset', 'invalid_cursor');
242→    const payload = bounded(items.slice(offset), ctx.budgetTokens); const next = offset + payload.length; const truncated = next < items.length;
243→    return Object.freeze({ op: artifact.op, status: truncated ? 'needs_resume' : 'ok', summary: `resumed ${payload.length} behavior records`, payload, refs: [ref], ...(truncated ? { cursor: `atlas-behavior:${ref.digest}:${next}` } : {}), cost: { tokens_out: Math.ceil(Buffer.byteLength(JSON.stringify(payload)) / 4), wall_ms: 0, usd: 0, underlying: `node-permission-model@${process.version}` }, provenance: { artifactDigest: ref.digest, resumed_from: offset, deterministic: true } });
244→  }
245→
246→  async reverify(claim, args, ctx) {
247→    const rerun = await this.invoke(claim?.op, args, ctx);
248→    return Object.freeze({ ok: rerun.refs[0].digest === claim?.refs?.[0]?.digest, observedDigest: rerun.refs[0].digest });
249→  }
250→}
